dashboard.definition:
{
    "title": "ServiceNow CMDB und ITSM",
    "description": "ServiceNow: CMDB-Beziehungen mit Impact, offene Incidents, Changes, Configuration Items und Assets",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "ci": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_rel": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:cmdb_rel_ci\" earliest=-7h parent_class!=\"cmdb_ci_medical_device\" child_class!=\"cmdb_ci_medical_device\"\n| stats latest(parent_class) as parent_class latest(child_class) as child_class by parent child\n| join type=left max=1 child [search index=demo_sakh sourcetype=\"cisco:dnac:devicehealth\" earliest=-15m | stats latest(Reachability) as child_status by DeviceName | rename DeviceName as child]\n| join type=left max=1 child [search index=demo_sakh sourcetype=\"snow:incident\" earliest=-24h priority<=2 | stats latest(state) as s by cmdb_ci | where s!=\"Geloest\" | eval inc_status=\"critical\" | rename cmdb_ci as child | fields child inc_status]\n| eval child_status=coalesce(inc_status, child_status, \"Operational\")\n| table parent parent_class child child_class child_status",
                "enableSmartSources": true
            },
            "name": "CMDB-Beziehungen mit Status"
        },
        "ds_inc": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:incident\" | stats latest(state) as state latest(priority) as priority latest(priority_label) as priority_label latest(short_description) as short_description latest(assignment_group) as assignment_group latest(cmdb_ci) as cmdb_ci latest(business_service) as business_service latest(opened_at) as opened_at latest(major_incident) as major by number",
                "enableSmartSources": true
            },
            "name": "Incidents"
        },
        "ds_k_open": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inc",
                "query": "| where state!=\"Geloest\" | stats count as \"Offene Incidents\""
            }
        },
        "ds_k_p1": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inc",
                "query": "| where state!=\"Geloest\" AND priority=1 | stats count as \"P1 offen\""
            }
        },
        "ds_k_major": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inc",
                "query": "| where major=\"true\" OR major=1 | stats count as \"Major Incidents\""
            }
        },
        "ds_chg": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:change_request\" earliest=-20m\n| stats latest(type) as Typ latest(state) as Status latest(short_description) as Beschreibung latest(risk) as Risiko latest(assignment_group) as Gruppe latest(cmdb_ci) as CI latest(start_date) as Start latest(end_date) as Ende latest(close_code) as Abschluss by number\n| eval o=case(Status=\"Implementierung\", 0, Typ=\"Emergency\", 1, Status=\"Genehmigung\", 2, Status=\"Geplant\", 3, Status=\"Bewertung\", 4, Status=\"Neu\", 5, Status=\"Review\", 6, true(), 7)\n| sort o Start | fields - o | rename number as Change",
                "enableSmartSources": true
            },
            "name": "Changes (aktueller Stand)"
        },
        "ds_k_chg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_chg",
                "query": "| where Status!=\"Geschlossen\" | stats count as \"Offene Changes\""
            }
        },
        "ds_k_emg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_chg",
                "query": "| where Typ=\"Emergency\" AND Status!=\"Geschlossen\" | stats count as \"Notfall-Changes\""
            }
        },
        "ds_chg_state": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_chg",
                "query": "| stats count by Status"
            }
        },
        "ds_k_ci": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:cmdb_ci_*\" earliest=-7h | stats dc(sys_id) as CIs",
                "enableSmartSources": true
            }
        },
        "ds_inc_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inc",
                "query": "| search cmdb_ci=\"$ci$\" | where state!=\"Geloest\"\n| sort priority - opened_at | table number priority_label state business_service cmdb_ci assignment_group short_description opened_at\n| rename number as Incident priority_label as Prioritaet state as Status business_service as Service cmdb_ci as CI assignment_group as Gruppe short_description as Beschreibung opened_at as Eroeffnet"
            }
        },
        "ds_inc_group": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:incident\" state=\"Neu\" | timechart span=1h dc(number) by assignment_group",
                "enableSmartSources": true
            }
        },
        "ds_inc_svc": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inc",
                "query": "| stats count as Incidents by business_service | sort - Incidents | rename business_service as Service"
            }
        },
        "ds_ci_class": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:cmdb_ci_*\" earliest=-7h | stats dc(sys_id) as CIs by sys_class_name | sort - CIs | rename sys_class_name as Klasse",
                "enableSmartSources": true
            }
        },
        "ds_assets": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"snow:alm_asset\" earliest=-7h | stats latest(cost) as cost latest(model_category) as cat by asset_tag | stats sum(cost) as EUR count as Assets by cat | eval \"Wert (Mio EUR)\"=round(EUR / 1000000, 2) | fields cat Assets \"Wert (Mio EUR)\" | rename cat as Kategorie",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_home.svg",
                "preserveAspectRatio": true
