                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 10,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 10,
                        "to": 20,
                        "value": "#c98a00"
